-- Virtual Lab core library: three ready-made experiments each for Physics, Chemistry and Biology,
-- with their steps, questions and graphs, shared with the departments that teach them.
-- Safe to re-run: a deleted copy is restored rather than duplicated, and steps/questions are only
-- added where missing so existing student attempts are never touched.

-- ================= Simple Pendulum (physics) =================
VALUES ((SELECT s.id FROM `subjects` s WHERE s.deleted_at IS NULL AND (s.name LIKE 'phy%' OR s.code LIKE 'phy%') ORDER BY s.id LIMIT 1), 'Simple Pendulum', 'Oscillations', 'physics', 'intermediate', '2d', 'pendulum', 'simple_pendulum', '1', 'pendulum-2d-v1', '0', '25', NULL, NULL, NULL, NULL, 'To measure the period of a simple pendulum and use it to estimate the acceleration due to gravity.', 'A simple pendulum swings with a period that depends on its length. In this practical you will measure the pendulum\'s length with a ruler, time a number of oscillations with a real stopwatch, and calculate the period. Publish a second copy of this experiment with a different specimen length to compare how period changes with length.', 'Pendulum bob on a string, ruler, stopwatch.', 'None (all apparatus is simulated).', 'None.', '[{\"key\":\"bob1\",\"object_type\":\"specimen\",\"position\":{\"x\":-0.8,\"y\":0,\"z\":0},\"props\":{\"length_cm\":25,\"mass_g\":50}},{\"key\":\"ruler1\",\"object_type\":\"ruler\",\"position\":{\"x\":0.8,\"y\":0,\"z\":0.8}},{\"key\":\"stopwatch1\",\"object_type\":\"stopwatch\",\"position\":{\"x\":0.8,\"y\":0,\"z\":-0.8}}]', 'How would you expect the period to change if the pendulum were made longer? Explain using your results.', '15.00', NULL, 1, 'published', NOW(), NOW())
