-- ================= Investigating Hooke's Law (physics) =================
VALUES ((SELECT s.id FROM `subjects` s WHERE s.deleted_at IS NULL AND (s.name LIKE 'phy%' OR s.code LIKE 'phy%') ORDER BY s.id LIMIT 1), 'Investigating Hooke\'s Law', 'Forces', 'physics', 'intermediate', '2d', 'hookes_law', 'hookes_law', '1', 'hookes-law-2d-v1', '0', '40', NULL, NULL, NULL, NULL, 'To investigate the relationship between the force applied to a spring and its extension.', 'Hooke\'s Law states that the extension of a spring is directly proportional to the force applied, provided the elastic limit is not exceeded (F = kx). In this practical you will mount a spring, load it with a series of known masses, and measure its real extension at each load.', 'Retort stand, spring, mass pieces (50g, 100g, 150g, 200g), ruler.', 'None (all apparatus is simulated).', 'Do not exceed the spring\'s safe load - watch for the overload warning and record it as an observation if it appears.', '[{\"key\":\"stand1\",\"object_type\":\"retort_stand\",\"position\":{\"x\":-1.5,\"y\":0,\"z\":0},\"in_tray\":true},{\"key\":\"spring1\",\"object_type\":\"spring\",\"position\":{\"x\":-1.5,\"y\":0,\"z\":0.9},\"props\":{\"natural_length_cm\":15,\"spring_constant_n_per_m\":40,\"max_safe_extension_cm\":12},\"in_tray\":true},{\"key\":\"ruler1\",\"object_type\":\"ruler\",\"position\":{\"x\":1.5,\"y\":0,\"z\":0},\"in_tray\":true},{\"key\":\"mass50\",\"object_type\":\"mass_piece\",\"position\":{\"x\":0.4,\"y\":0,\"z\":1.2},\"props\":{\"mass_g\":50},\"in_tray\":true},{\"key\":\"mass100\",\"object_type\":\"mass_piece\",\"position\":{\"x\":0.85,\"y\":0,\"z\":1.2},\"props\":{\"mass_g\":100},\"in_tray\":true},{\"key\":\"mass150\",\"object_type\":\"mass_piece\",\"position\":{\"x\":1.3,\"y\":0,\"z\":1.2},\"props\":{\"mass_g\":150},\"in_tray\":true},{\"key\":\"mass200\",\"object_type\":\"mass_piece\",\"position\":{\"x\":1.75,\"y\":0,\"z\":1.2},\"props\":{\"mass_g\":200},\"in_tray\":true}]', 'Based on your Force vs Extension results, does the spring obey Hooke\'s Law? Explain, referring to your results table.', '20.00', NULL, 1, 'published', NOW(), NOW())
