-- ================= Ohm's Law (physics) =================
VALUES ((SELECT s.id FROM `subjects` s WHERE s.deleted_at IS NULL AND (s.name LIKE 'phy%' OR s.code LIKE 'phy%') ORDER BY s.id LIMIT 1), 'Ohm\'s Law', 'Electricity and Circuits', 'physics', 'intermediate', '2d', 'circuit', 'ohms_law', '1', 'circuit-2d-v1', '0', '30', NULL, NULL, NULL, NULL, 'To investigate the relationship between voltage, current and resistance in a simple circuit.', 'Ohm\'s Law states that the current through a conductor is directly proportional to the voltage across it, provided temperature stays constant. In this practical you will build a simple series circuit and use it to verify this relationship.', 'Battery, switch, resistor, ammeter, voltmeter, connecting wires.', 'None (all apparatus is simulated).', 'Ensure the circuit is switched off before making or changing any connection.', '[{\"key\":\"battery1\",\"object_type\":\"battery\",\"position\":{\"x\":-3,\"y\":0,\"z\":0}},{\"key\":\"switch1\",\"object_type\":\"switch\",\"position\":{\"x\":-1.5,\"y\":0,\"z\":0}},{\"key\":\"resistor1\",\"object_type\":\"resistor\",\"position\":{\"x\":0,\"y\":0,\"z\":0}},{\"key\":\"ammeter1\",\"object_type\":\"ammeter\",\"position\":{\"x\":1.6,\"y\":0,\"z\":0.9}},{\"key\":\"voltmeter1\",\"object_type\":\"voltmeter\",\"position\":{\"x\":1.6,\"y\":0,\"z\":-0.9}}]', 'Based on your measurements, what can you conclude about the relationship between voltage and current?', '20.00', NULL, 1, 'published', NOW(), NOW())
