-- ================= Acid-Base Titration (chemistry) =================
VALUES ((SELECT s.id FROM `subjects` s WHERE s.deleted_at IS NULL AND (s.name LIKE 'chem%' OR s.code LIKE 'chem%') ORDER BY s.id LIMIT 1), 'Acid-Base Titration', 'Acids, Bases and Salts', 'chemistry', 'intermediate', '2d', 'titration', 'acid_base_titration', '1', 'titration-2d-v1', '0', '40', NULL, NULL, NULL, NULL, 'To determine the concentration of a sodium hydroxide solution by titrating it against a hydrochloric acid solution of known concentration.', 'Titration is used to find the concentration of an unknown solution by reacting it with a solution of known concentration until the reaction is exactly complete, shown by an indicator colour change. Collect your glassware from the tray before you begin.', 'Burette, conical flask, pipette, retort stand, indicator.', 'Dilute hydrochloric acid (0.1M), sodium hydroxide solution, phenolphthalein indicator.', 'Wear safety goggles at all times. Handle acids and bases with care and avoid skin contact.', '[{\"key\": \"burette1\", \"object_type\": \"burette\", \"position\": {\"x\": -1, \"y\": 0, \"z\": 0}, \"props\": {\"liquid\": \"HCl (0.1M)\", \"color\": \"#7dd3fc\", \"capacity_ml\": 50, \"titrant_concentration_m\": 0.1}, \"in_tray\": true}, {\"key\": \"flask1\", \"object_type\": \"beaker\", \"position\": {\"x\": -1, \"y\": 0, \"z\": 1.4}, \"props\": {\"liquid\": \"\", \"color\": \"#f9a8d4\", \"capacity_ml\": 100, \"current_volume\": 0, \"analyte_concentration_m\": 0.0992}, \"in_tray\": true}, {\"key\": \"pipette1\", \"object_type\": \"pipette\", \"position\": {\"x\": 1.4, \"y\": 0, \"z\": 0.6}, \"in_tray\": true}]', 'What does the colour change at the endpoint tell you about the reaction?', '20.00', NULL, 1, 'published', NOW(), NOW())
