-- ================= Heating Water and Measuring Temperature Change (chemistry) =================
VALUES ((SELECT s.id FROM `subjects` s WHERE s.deleted_at IS NULL AND (s.name LIKE 'chem%' OR s.code LIKE 'chem%') ORDER BY s.id LIMIT 1), 'Heating Water and Measuring Temperature Change', 'Heat and Energy', 'chemistry', 'beginner', '3d', NULL, 'heating_water_temperature', '1', '3d-v1', '0', '25', 'Using a thermometer and stopwatch to track a real physical change over time.', 'Students will heat water and record real temperature readings against real elapsed time.', 'Basic use of a thermometer, and what temperature measures.', '[\"reading_scales\", \"recording_observations\"]', 'To measure how the temperature of water changes with heating time.', 'Heating a liquid increases the average kinetic energy of its particles, raising its temperature. In this practical you will heat water and track its real temperature rise over time.', 'Beaker, Bunsen burner, thermometer, stopwatch.', 'Water.', 'Keep hands and loose clothing away from the flame. Never leave a heated beaker unattended.', '[{\"key\":\"beaker1\",\"object_type\":\"beaker\",\"position\":{\"x\":-1,\"y\":0,\"z\":0},\"props\":{\"color\":\"#a9d6e5\",\"capacity_ml\":250,\"current_volume\":150},\"in_tray\":true},{\"key\":\"burner1\",\"object_type\":\"bunsen_burner\",\"position\":{\"x\":-1,\"y\":0,\"z\":-1},\"in_tray\":true},{\"key\":\"thermometer1\",\"object_type\":\"thermometer\",\"position\":{\"x\":0.5,\"y\":0,\"z\":0.8},\"in_tray\":true},{\"key\":\"stopwatch1\",\"object_type\":\"stopwatch\",\"position\":{\"x\":0.5,\"y\":0,\"z\":-0.8},\"in_tray\":true}]', 'How did the water\'s temperature change over time? Was the rate of change constant?', '15.00', NULL, 1, 'published', NOW(), NOW())
