-- ================= Measuring 50ml of Water (chemistry) =================
VALUES ((SELECT s.id FROM `subjects` s WHERE s.deleted_at IS NULL AND (s.name LIKE 'chem%' OR s.code LIKE 'chem%') ORDER BY s.id LIMIT 1), 'Measuring 50ml of Water', 'Measurement and Volume', 'chemistry', 'beginner', '3d', NULL, 'measuring_50ml_water', '1', '3d-v1', '0', '15', NULL, NULL, NULL, NULL, 'To accurately measure a fixed volume of liquid using a measuring cylinder.', 'Measuring cylinders are graduated so you can read off a liquid\'s volume directly. Pour carefully and read the scale at eye level - stopping at exactly the target volume takes practice, so a small tolerance is allowed.', 'Measuring cylinder, water container.', 'Water.', 'None.', '[{\"key\":\"container1\",\"object_type\":\"water_container\",\"position\":{\"x\":-1,\"y\":0,\"z\":0}},{\"key\":\"cylinder1\",\"object_type\":\"measuring_cylinder\",\"position\":{\"x\":1,\"y\":0,\"z\":0},\"props\":{\"current_volume\":0}}]', 'How close did you get to exactly 50ml, and what would you do differently to be more precise next time?', '10.00', NULL, 1, 'published', NOW(), NOW())
