-- ================= Viewing Onion Cells Using a Microscope (biology) =================
VALUES ((SELECT s.id FROM `subjects` s WHERE s.deleted_at IS NULL AND (s.name LIKE 'bio%' OR s.code LIKE 'bio%') ORDER BY s.id LIMIT 1), 'Viewing Onion Cells Using a Microscope', 'Cell Biology', 'biology', 'beginner', '2d', 'microscope', 'onion_epidermal_cells', '1', 'microscope-2d-v1', '0', '30', NULL, NULL, NULL, NULL, 'To prepare a microscope and correctly focus it to observe the structure of onion epidermal cells.', 'A microscope must be set up, lit and focused correctly before a specimen can be seen clearly. In this practical you will place a prepared onion slide on the stage, find it at low power, and bring it into sharp focus before increasing magnification.', 'Microscope, prepared onion epidermal slide.', 'None (all apparatus is simulated).', 'Handle the microscope and glass slide with care.', '[{\"key\":\"microscope1\",\"object_type\":\"microscope\",\"position\":{\"x\":0,\"y\":0,\"z\":0},\"in_tray\":true},{\"key\":\"slide1\",\"object_type\":\"biological_model\",\"position\":{\"x\":1.4,\"y\":0,\"z\":0.6},\"props\":{\"specimen\":\"Onion epidermal cells\",\"optimal_focus\":58,\"focus_tolerance\":6,\"expected_structures\":\"the cell wall, nucleus and cytoplasm of the onion epidermal cells\"},\"in_tray\":true}]', 'What did focusing the microscope teach you about how magnification and focus affect what you can observe?', '15.00', NULL, 1, 'published', NOW(), NOW())
