-- ================= Viewing Cheek Cells Using a Microscope (biology) =================
VALUES ((SELECT s.id FROM `subjects` s WHERE s.deleted_at IS NULL AND (s.name LIKE 'bio%' OR s.code LIKE 'bio%') ORDER BY s.id LIMIT 1), 'Viewing Cheek Cells Using a Microscope', 'Cell Biology', 'biology', 'intermediate', '2d', 'microscope', 'cheek_cells', '1', 'microscope-2d-v1', '0', '30', 'Operating a microscope to observe and compare animal cell structure.', 'Students will focus a microscope on cheek epithelial cells and identify structures that distinguish animal cells from plant cells.', 'Basic microscope operation (ideally after Viewing Onion Epidermal Cells).', '[\"microscope_handling\", \"focusing_microscope\", \"recording_observations\"]', 'To observe and identify the structures of human cheek epithelial cells using a microscope.', 'Cheek cells are a convenient example of animal cells. Unlike plant cells, they have no cell wall or chloroplasts, giving them an irregular rather than boxy shape.', 'Microscope, prepared cheek cell slide.', 'None (all apparatus is simulated).', 'Handle the microscope and slide with care.', '[{\"key\":\"microscope1\",\"object_type\":\"microscope\",\"position\":{\"x\":0,\"y\":0,\"z\":0},\"in_tray\":true},{\"key\":\"slide1\",\"object_type\":\"biological_model\",\"position\":{\"x\":1.4,\"y\":0,\"z\":0.6},\"props\":{\"specimen\":\"Human cheek epithelial cells\",\"optimal_focus\":45,\"focus_tolerance\":7,\"expected_structures\":\"the cell membrane, cytoplasm and nucleus of the cheek cells - notice there is no cell wall, unlike the onion cells\",\"cell_color\":\"#fbcfe8\",\"nucleus_color\":\"#9d174d\"},\"in_tray\":true}]', 'How did the cheek cells differ in shape and structure from the onion cells you observed before?', '15.00', NULL, 1, 'published', NOW(), NOW())
