-- ================= Microscope Handling Practice (biology) =================
VALUES ((SELECT s.id FROM `subjects` s WHERE s.deleted_at IS NULL AND (s.name LIKE 'bio%' OR s.code LIKE 'bio%') ORDER BY s.id LIMIT 1), 'Microscope Handling Practice', 'Microscope Skills', 'biology', 'beginner', '2d', 'microscope', 'microscope_handling_practice', '1', 'microscope-2d-v1', '0', '15', 'Basic, confident handling and focusing of a microscope.', 'Students will practise the core mechanical skill of setting up and focusing a microscope before attempting a graded specimen practical.', 'None - this is an introductory practice exercise.', '[\"microscope_handling\", \"focusing_microscope\"]', 'To practise setting up, illuminating and focusing a microscope at low power.', 'Before observing real specimens, it helps to practise the basic mechanics of microscope use: placing a slide, switching on the light, and focusing.', 'Microscope, practice slide.', 'None (all apparatus is simulated).', 'Handle the microscope and slide with care.', '[{\"key\":\"microscope1\",\"object_type\":\"microscope\",\"position\":{\"x\":0,\"y\":0,\"z\":0},\"in_tray\":true},{\"key\":\"slide1\",\"object_type\":\"biological_model\",\"position\":{\"x\":1.4,\"y\":0,\"z\":0.6},\"props\":{\"specimen\":\"Practice specimen\",\"optimal_focus\":50,\"focus_tolerance\":10,\"expected_structures\":\"a simple practice pattern\",\"cell_color\":\"#a5f3fc\",\"nucleus_color\":\"#155e75\"},\"in_tray\":true}]', 'What did you find hardest about setting up and focusing the microscope?', '10.00', NULL, 1, 'published', NOW(), NOW())
