    `subject_id` = COALESCE(VALUES(`subject_id`), `subject_id`), `is_template` = 1, `status` = 'published', `deleted_at` = NULL, `updated_at` = NOW();
SET @e = (SELECT id FROM `virtual_lab_experiments` WHERE `template_key` = 'microscope_handling_practice');
SELECT @e, s.department_id FROM `subjects` s WHERE s.deleted_at IS NULL AND s.department_id IS NOT NULL AND (s.name LIKE 'bio%' OR s.code LIKE 'bio%');

-- Any of these still not shared with a department (no matching subject) go to every department;
-- the admin can narrow them from Virtual Lab > Experiments > Library > Departments.
SELECT e.id, d.id FROM `virtual_lab_experiments` e CROSS JOIN `departments` d
WHERE e.template_key IN ('simple_pendulum', 'hookes_law', 'ohms_law', 'acid_base_titration', 'heating_water_temperature', 'measuring_50ml_water', 'onion_epidermal_cells', 'cheek_cells', 'microscope_handling_practice') AND e.deleted_at IS NULL
  AND NOT EXISTS (SELECT 1 FROM `virtual_lab_experiment_departments` x WHERE x.experiment_id = e.id);
